styl:
.brad-full.b-iq-text-48 {  border-radius: 32px !important;  }
.white-bg.b-iq-text-48 {  background-color: #fff;  }
.b-iq-text-48 .middle-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle;  }
@media screen and (max-width: 600px) {
  .b-iq-text-48 .middle-title {  font-size: 28px !important;
    line-height: 34px !important;  }
}
.b-iq-text-48 .text {  font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400;  }
.b-iq-text-48 .text.bold {  font-weight: 700;  }
.b-iq-text-48 .pb12 {  padding-bottom: 12px !important;  }
.b-iq-text-48 .pb32 {  padding-bottom: 32px;  }
.b-iq-text-48 .pb44 {  padding-bottom: 44px;  }
.b-iq-text-48 .pt44 {  padding-top: 44px;  }
@media screen and (max-width: 600px) {
  .b-iq-text-48 .text.mob-text, .b-iq-text-48 .grey-text.mob-text {  font-size: 17px !important;  }
}
.b-iq-text-48 .orange-block {  background: url("https://fsms.quadcode.com/storage/public/d6/o2/ua3ursrq72d917s0/bcg.png") center no-repeat;
  background-size: cover;
  background-color: #fff8f0;
  border-radius: 24px;  }
.b-iq-text-48 .left-text-block {  display: inline-block;
  width: 232px;
  vertical-align: top;
  padding: 24px 12px 24px 32px;  }
@media screen and (max-width: 600px) {
  .b-iq-text-48 .left-text-block {  width: auto !important;
    display: block !important;
